// @ts-nocheck
// Director of Service — Sales Decisions V1.2: 36 two-pick scenarios across six categories for someone who delivers what
// was sold, protects the renewal, and finds the next dollar. Transcribed from Peak's October 2026 brief (V1 + the V1.1
// addendum, S-35 and S-36). Scores are quality-based 0–100, not a fixed ladder; scores under 25 mean real revenue, trust,
// or accountability risk. The least-likely pick is normalized: (highest − picked) ÷ (highest − lowest) × 100, so ruling
// out the riskiest move always earns 100. Failure-profile reads create interview probes only.
const LABEL = { bench: "Benchmark", def: "Defensible alternative", know: "Knowledge / experience gap", judg: "Judgment concern", risk: "Role / behavioral risk" };
// sv(id, category, title, [construct, main signal], stem, options, why, miss, probe, notes?)
// option: [score, text, cls, sub, reason, { flag?, positive?, profile? }]
const sv = (id, comp, title, meta, text, opts, why, miss, probe, notes) => ({
  id, comp, kind: "scenario", title, construct: meta[0], itemType: "Scenario · most likely + least likely", mainSignal: meta[1], text, why, miss, probe,
  calibrate: (notes && notes.calibrate) || "", gameability: (notes && notes.gameability) || "",
  opts: opts.map(([score, t, cls, sub, reason, x], i) => ({ i, score, text: t, cls, interp: LABEL[cls] + (sub ? " \u00b7 " + sub : ""), reason, flag: (x && x.flag) || null, positive: (x && x.positive) || null, profile: (x && x.profile) || null, sev: cls === "risk" ? "critical" : null })),
});

